<script lang="ts">
	import{onMount}from'svelte';import{Activity,Check,RefreshCw,Save,Settings2}from'@lucide/svelte';import EventTable from'./DischargeEventTable.svelte';import{activateBaselineEvent,createDischargeEvent,deleteDischargeEvent,getDischargeConfig,hasBmsSession,listBmsStrings,listDischargeEvents,listDischargeSamples,saveDischargeConfig,stopDischargeEvent,type BaselineCapacitySource,type BatteryString,type DischargeConfig,type DischargeEvent,type DischargeEventType,type DischargeSample}from'$lib/services/bms-api';
	let strings=$state<BatteryString[]>([]),events=$state<DischargeEvent[]>([]),samples=$state<DischargeSample[]>([]);let selectedIndex=$state(0),selectedEventId=$state<number|null>(null);let tab=$state<'event'|'history'>('event');let eventType=$state<DischargeEventType>('BASELINE_CALIBRATION');let source=$state<BaselineCapacitySource>('NOMINAL_CAPACITY');let startTime=$state(localDate());let configOpen=$state(false),saving=$state(false),notice=$state(''),error=$state('');
	let config=$state<DischargeConfig>({id:1,dischargeCurrentDirection:'NEGATIVE',automaticMode:true,automaticStartCurrentA:6,automaticStopCurrentA:0,sampleIntervalSeconds:1800,timeScaleFactor:1,invalidSampleLimit:5,risingVoltageSampleLimit:5,updatedAt:null});
	let selectedString=$derived(strings.find(s=>s.stringIndex===Number(selectedIndex))??null);let strId=$derived(selectedString?`str${selectedString.stringIndex}`:'');let filtered=$derived(events.filter(e=>e.strId===strId).sort((a,b)=>b.id-a.id));let selectedEvent=$derived(filtered.find(e=>e.id===selectedEventId)??filtered[0]??null);let baseline=$derived(filtered.find(e=>e.status==='SUCCESS'&&e.activeBaseline)??null);
	onMount(async()=>{if(!hasBmsSession())return;await loadAll()});
	async function loadAll(){error='';try{strings=await listBmsStrings();selectedIndex=selectedIndex||strings[0]?.stringIndex||0;[config,events]=await Promise.all([getDischargeConfig(),listDischargeEvents()]);selectedEventId=filtered[0]?.id??null;await loadSamples()}catch(e){error=msg(e)}}
	async function refresh(){try{events=await listDischargeEvents();await loadSamples();notice='Discharge data refreshed.'}catch(e){error=msg(e)}}async function loadSamples(){samples=selectedEvent&&hasBmsSession()?await listDischargeSamples(selectedEvent.id):[]}
	async function schedule(){if(!selectedString)return;busy(async()=>{await createDischargeEvent(strId,new Date(startTime),selectedString!.ratedCapacity,config.automaticMode,config.automaticStartCurrentA,eventType,eventType==='BASELINE_CALIBRATION'?'NOMINAL_CAPACITY':source);notice='Discharge event scheduled.';await refresh()})}
	async function stop(event:DischargeEvent){busy(async()=>{await stopDischargeEvent(event.id);notice='Stop requested.';await refresh()})}async function remove(event:DischargeEvent){if(!confirm(`Delete discharge event ${event.id}?`))return;busy(async()=>{await deleteDischargeEvent(event.id);notice='Event deleted.';await refresh()})}async function activate(event:DischargeEvent){busy(async()=>{await activateBaselineEvent(strId,event.id);notice='Baseline activated.';await refresh()})}
	async function saveConfig(){busy(async()=>{config=await saveDischargeConfig({...config,sampleIntervalSeconds:Math.max(1,Number(config.sampleIntervalSeconds)),timeScaleFactor:Math.max(.000001,Number(config.timeScaleFactor)),invalidSampleLimit:Math.max(1,Number(config.invalidSampleLimit)),risingVoltageSampleLimit:Math.max(1,Number(config.risingVoltageSampleLimit))});configOpen=false;notice='Discharge configuration saved.'})}
	async function busy(run:()=>Promise<void>){saving=true;error='';try{if(hasBmsSession())await run();else notice='API payload is ready; authenticate to submit it.'}catch(e){error=msg(e)}finally{saving=false}}function msg(e:unknown){return e instanceof Error?e.message:'Request failed.'}function localDate(){const d=new Date(),p=(n:number)=>String(n).padStart(2,'0');return`${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}
</script>
<section class="page"><div class="head"><div><h2><Activity size={23}/>Discharge Calibration</h2><p>Create discharge events, follow samples to Vcutoff, and review SoH history.</p></div><button class="secondary" onclick={refresh}><RefreshCw size={16}/>Refresh</button></div><div class="tabs"><button class:active={tab==='event'} onclick={()=>tab='event'}>Discharge Event</button><button class:active={tab==='history'} onclick={()=>tab='history'}>Discharge Event History</button></div>{#if notice}<div class="notice"><Check size={16}/>{notice}</div>{/if}{#if error}<div class="error">{error}</div>{/if}
	{#if tab==='event'}<section class="panel controls"><label>String<select bind:value={selectedIndex} onchange={async()=>{selectedEventId=null;await refresh()}}><option value={0}>No string configured</option>{#each strings as s}<option value={s.stringIndex}>str{s.stringIndex} — {s.stringName}</option>{/each}</select></label><label>Start time<input type="datetime-local" bind:value={startTime}/></label><label>Event type<select bind:value={eventType} onchange={()=>source=eventType==='BASELINE_CALIBRATION'?'NOMINAL_CAPACITY':baseline?'BASELINE_EVENT':'NOMINAL_CAPACITY'}><option value="BASELINE_CALIBRATION">Baseline calibration</option><option value="SOH_CHECK">SoH check</option></select></label>{#if eventType==='SOH_CHECK'}<label>Reference capacity source<select bind:value={source}><option value="BASELINE_EVENT" disabled={!baseline}>Active baseline event</option><option value="NOMINAL_CAPACITY">Rated capacity</option></select></label>{/if}<label>Rated capacity (Ah)<input value={selectedString?.ratedCapacity??''} disabled/></label><button class="secondary" onclick={()=>configOpen=true}><Settings2 size={16}/>Config</button><button class="primary" disabled={saving||!strId} onclick={schedule}>Schedule Event</button></section>
	<section class="panel"><div class="panel-title"><div><h3>Selected Discharge Event</h3><p>{baseline?`Active reference: Event ${baseline.id}`:'No active reference baseline yet'}</p></div></div><EventTable items={selectedEvent?[selectedEvent]:[]} onselect={async(e)=>{selectedEventId=e.id;await loadSamples()}} onstop={stop} onremove={remove} onactivate={activate}/></section>
	<section class="panel"><div class="panel-title"><div><h3>Discharge Samples</h3><p>Data returned by bms.tools.discharge.samples.</p></div></div><div class="table"><table><thead><tr><th>Time</th><th>Avg voltage</th><th>Domain current</th><th>Raw current</th><th>Used Ah</th><th>Temperature</th></tr></thead><tbody>{#if samples.length}{#each samples as s}<tr><td>{new Date(s.sampleTime).toLocaleString()}</td><td>{s.avgVoltageV??'—'}</td><td>{s.domainCurrentA??'—'}</td><td>{s.rawCurrentA??'—'}</td><td>{s.usedAh??'—'}</td><td>{s.temperatureC??'—'}</td></tr>{/each}{:else}<tr><td colspan="6" class="empty">No samples for the selected event.</td></tr>{/if}</tbody></table></div></section>
	{:else}<section class="panel"><div class="panel-title"><div><h3>Discharge Event History</h3><p>All baseline calibration and SoH check events.</p></div></div><EventTable items={filtered} onselect={async(e)=>{selectedEventId=e.id;await loadSamples()}} onstop={stop} onremove={remove} onactivate={activate}/></section>{/if}
</section>
{#if configOpen}<div class="backdrop" onclick={()=>configOpen=false}><dialog open onclick={e=>e.stopPropagation()}><header><div><h3>Discharge configuration</h3><p>Exact parameters from bms.tools.discharge.saveConfig.</p></div></header><div class="config-grid"><label>Current direction<select bind:value={config.dischargeCurrentDirection}><option value="NEGATIVE">Raw negative = discharge</option><option value="POSITIVE">Raw positive = discharge</option></select></label><label class="check"><input type="checkbox" bind:checked={config.automaticMode}/>Automatic mode</label><label>Automatic start current (A)<input type="number" bind:value={config.automaticStartCurrentA}/></label><label>Automatic stop current (A)<input type="number" bind:value={config.automaticStopCurrentA}/></label><label>Sample interval (seconds)<input type="number" min="1" bind:value={config.sampleIntervalSeconds}/></label><label>Time scale factor<input type="number" min=".000001" step=".1" bind:value={config.timeScaleFactor}/></label><label>Invalid sample limit<input type="number" min="1" bind:value={config.invalidSampleLimit}/></label><label>Rising voltage sample limit<input type="number" min="1" bind:value={config.risingVoltageSampleLimit}/></label></div><footer><button class="secondary" onclick={()=>configOpen=false}>Cancel</button><button class="primary" onclick={saveConfig}><Save size={16}/>Save</button></footer></dialog></div>{/if}
<style>
	.page{animation:in .18s ease}.head{display:flex;justify-content:space-between;gap:18px;margin-bottom:16px}.head h2{display:flex;align-items:center;gap:9px;margin:0;color:#172b4d;font-size:24px;font-weight:500}.head p{margin:7px 0 0;color:#718096;font-size:16px}.tabs{display:flex;margin-bottom:15px;border-bottom:1px solid #e1e7f0}.tabs button{height:40px;padding:0 13px;border:0;border-bottom:2px solid transparent;color:#66748a;background:transparent;font:inherit;cursor:pointer}.tabs button.active{border-color:#2454b6;color:#1749ad}.panel{margin-bottom:15px;overflow:hidden;border:1px solid #e1e7f0;border-radius:11px;background:#fff}.controls{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));align-items:end;gap:12px;padding:16px}.controls label,.config-grid label{display:grid;gap:6px;color:#536078;font-size:13px}input,select{width:100%;height:39px;padding:0 10px;border:1px solid #d7dfeb;border-radius:7px;color:#273853;background:#fff;font:inherit}.primary,.secondary{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;padding:0 13px;border-radius:8px;font:inherit;cursor:pointer}.primary{border:0;color:#fff;background:#1749ad}.secondary{border:1px solid #d7dfeb;color:#40516f;background:#fff}.panel-title{display:flex;justify-content:space-between;padding:16px 18px;border-bottom:1px solid #edf0f4}.panel-title h3{margin:0;color:#31415c;font-size:16px;font-weight:500}.panel-title p{margin:4px 0 0;color:#8792a4;font-size:12px}.table{overflow-x:auto}.table table{width:100%;min-width:800px;border-collapse:collapse}th,td{padding:12px 14px;border-bottom:1px solid #edf1f6;color:#56657c;font-size:13px;text-align:left}th{color:#7b879a;background:#f8faff;font-size:11px;font-weight:500;text-transform:uppercase}.empty{height:130px;text-align:center}.badge{padding:4px 7px;border-radius:11px;color:#31569f;background:#edf3ff;font-size:11px}.row-actions{display:flex;justify-content:flex-end;gap:5px}.row-actions button{display:grid;width:30px;height:30px;place-items:center;border:1px solid #dce6fb;border-radius:7px;color:#31569f;background:#f6f9ff;cursor:pointer}.row-actions .danger{color:#c83229;background:#fff6f5;border-color:#f3d8d5}.notice,.error{margin-bottom:13px;padding:10px 12px;border-radius:8px;font-size:13px}.notice{display:flex;align-items:center;gap:7px;color:#28784e;background:#f2fbf5;border:1px solid #cae7d5}.error{color:#b42318;background:#fff1f0;border:1px solid #f3cac6}.backdrop{position:fixed;inset:0;z-index:30;display:grid;place-items:center;padding:14px;background:rgba(24,35,58,.25)}dialog{position:relative;width:min(560px,100%);margin:0;padding:0;border:1px solid #e1e7f0;border-radius:11px;background:#fff}dialog header{padding:16px 19px;border-bottom:1px solid #edf0f4}dialog h3{margin:0;color:#31415c;font-size:18px;font-weight:500}dialog p{margin:4px 0 0;color:#8792a4;font-size:12px}.config-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px;padding:18px}.config-grid .check{display:flex;align-items:center}.check input{width:16px;height:16px}dialog footer{display:flex;justify-content:flex-end;gap:8px;padding:11px 18px;border-top:1px solid #edf0f4}@keyframes in{from{opacity:0;transform:translateY(4px)}}@media(max-width:1050px){.controls{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.head{flex-direction:column}.controls,.config-grid{grid-template-columns:1fr}}
</style>
